"use client";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  GalleryInternalControls,
  galleryDistance,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface InfiniteParallaxSliderItem extends GalleryInternalItem {}
export interface InfiniteParallaxSliderProps extends GalleryInternalProps {
  items: readonly InfiniteParallaxSliderItem[];
  cardWidth?: number;
  gap?: number;
  parallax?: number;
  speed?: number;
  autoplay?: boolean;
  pauseOnHover?: boolean;
  drag?: boolean;
}
export function InfiniteParallaxSlider({
  items,
  cardWidth = 360,
  gap = 16,
  parallax = 0.22,
  speed = 0.16,
  autoplay = true,
  pauseOnHover = true,
  drag = true,
  index,
  defaultIndex,
  onChange,
  onSelect,
  height = 640,
  label = "Infinite parallax slider",
  className = "",
  style,
  renderCaption,
}: InfiniteParallaxSliderProps) {
  const env = useGalleryEnvironment();
  const width = Math.min(cardWidth, env.size.width * 0.82),
    step = width + gap;
  const motion = useGalleryMotion(
    items.length,
    { index, defaultIndex, onChange, drag, autoplay, speed, pauseOnHover, sensitivity: step },
    env,
  );
  const repeats = items.length
    ? Math.max(1, Math.ceil((env.size.width / step + 2) / items.length))
    : 0;
  const total = items.length * repeats;
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="infinite-parallax-slider"
      data-index={motion.current}
      data-phase={motion.phase.toFixed(4)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? "pan-y" : undefined,
        cursor: drag ? "grab" : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      {Array.from({ length: total }, (_, i) => {
        const item = items[i % items.length];
        const d = galleryDistance(i, motion.phase, total);
        const x = d * step;
        return (
          <button
            key={`${item.id}-${i}`}
            className="z-ag-card"
            type="button"
            data-gallery-card={i}
            tabIndex={i < items.length ? 0 : -1}
            aria-label={item.title ?? `Image ${i + 1}`}
            onClick={(event) => {
              if (event.detail === 0 || !motion.moved.current) onSelect?.(item, i % items.length);
            }}
            style={{
              width,
              height: Math.min(width * 1.33, env.size.height - 125),
              borderRadius: 8,
              transform: `translate(-50%,-50%) translate(${x}px,-15px)`,
              background: "#444",
            }}
          >
            <GalleryInternalImage
              item={item}
              className="z-ag-parallax-image"
              style={{
                width: `${100 + Math.abs(parallax) * 100}%`,
                maxWidth: "none",
                marginLeft: `-${Math.abs(parallax) * 50}%`,
                transform: `translateX(${-d * width * parallax * 0.3}px)`,
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: "linear-gradient(transparent 55%,#000b)",
              }}
            />
            <span
              className="z-ag-caption"
              style={{ transform: `translateX(${-d * width * parallax * 0.06}px)` }}
            >
              {renderCaption?.(item, i % items.length) ?? item.title}
            </span>
          </button>
        );
      })}
      <GalleryInternalControls
        current={motion.current}
        count={items.length}
        onPrevious={() => motion.choose(Math.round(motion.phase) - 1)}
        onNext={() => motion.choose(Math.round(motion.phase) + 1)}
        paused={motion.paused}
        onPause={autoplay ? () => motion.setPaused(!motion.paused) : undefined}
      />
      <div
        data-gallery-control
        style={{
          position: "absolute",
          bottom: 78,
          left: "50%",
          transform: "translateX(-50%)",
          display: "flex",
          gap: 8,
        }}
      >
        {items.map((item, i) => (
          <button
            key={item.id}
            type="button"
            aria-label={`Go to slide ${i + 1}`}
            aria-pressed={motion.current === i}
            onClick={() =>
              motion.choose(motion.phase + galleryDistance(i, motion.phase, items.length))
            }
            style={{
              width: motion.current === i ? 24 : 8,
              height: 8,
              padding: 0,
              border: 0,
              borderRadius: 9,
              background: motion.current === i ? "#111" : "#ccc",
            }}
          />
        ))}
      </div>
    </div>
  );
}
